#!/usr/bin/env python3
"""
把 https://tainan-calender.netlify.app/ 的活動資料抓下來，轉成一份乾淨的 markdown，
存到 knowledge/tainan_calendar.md，讓 bni_tainan agent 直接讀檔回答日期問題。

原因：這個頁面把一個很大的 base64 字型檔案內嵌在 <style> 裡，AI 用網頁擷取工具直接抓
整頁時，常常在讀到真正的活動資料前就被截斷，導致「看起來像JS動態載入」的誤判。
其實活動資料本身是寫死在 HTML 裡的靜態內容，用 html.parser 正規解析最穩定（不用正規表達式
硬猜巢狀結構，避免跨活動誤植資料）。
"""
import re
import sys
import urllib.request
from datetime import datetime, timezone, timedelta
from html.parser import HTMLParser

